function oldU(date){const s=date.toISOString().substr(0,10).split('-');return new Date(+s[0],+s[1]-1,+s[2])}
function newU(date){const o=date.getTimezoneOffset()*60000;date.setTime(date.getTime()-o);const s=date.toISOString().substr(0,10).split('-');return new Date(+s[0],+s[1]-1,+s[2])}
function judo(date){return new Date(date.getFullYear(),date.getMonth(),date.getDate())}
const fmt=d=>d.toDateString()
const inputs={
  'python ms (UTC midnight 2019-09-20)': Date.UTC(2019,8,20),
  'toDateString "Fri Sep 20 2019"': 'Fri Sep 20 2019',
  'ISO date "2019-09-20"': '2019-09-20',
}
for (const [k,v] of Object.entries(inputs)) {
  const inp=new Date(v)
  console.log(process.env.TZ.padEnd(20), k.padEnd(38), 'old:',fmt(oldU(new Date(v))),'| new:',fmt(newU(new Date(v))),'| judo:',fmt(judo(new Date(v))))
}
const d=new Date(Date.UTC(2019,8,20)); const before=d.getTime(); newU(d); console.log(process.env.TZ.padEnd(20),'argument mutated by new _unlocal_date:', d.getTime()!==before)
EOF
for tz in UTC Europe/Paris Europe/London Asia/Tokyo America/Los_Angeles America/New_York Pacific/Kiritimati Pacific/Pago_Pago; do TZ=$tz node unlocal.js; done

